    18→#[derive(Serialize, Deserialize, Debug, PartialEq, Clone)]
    19→#[serde(untagged)]
    20→pub struct ConfigAndPreset {
    21→    #[serde(flatten)]
    22→    pub config: Config,
    23→
    24→    #[serde(flatten)]
    25→    pub base_preset: BasePreset,
    26→    #[serde(flatten)]
    27→    pub altair_preset: AltairPreset,
    28→    #[serde(flatten)]
