    40→    #[superstruct(only(Gloas))]
    41→    #[serde(flatten)]
    42→    pub gloas_preset: GloasPreset,
    43→    /// The `extra_fields` map allows us to gracefully decode fields intended for future hard forks.
    44→    #[serde(flatten)]
    45→    pub extra_fields: HashMap<String, Value>,
