    47→
    48→impl ConfigAndPreset {
    49→    pub fn from_chain_spec<E: EthSpec>(spec: &ChainSpec) -> Self {
    50→        let mut config = Config::from_chain_spec::<E>(spec);
    51→        let base_preset = BasePreset::from_chain_spec::<E>(spec);
    52→        let altair_preset = AltairPreset::from_chain_spec::<E>(spec);
    53→        let bellatrix_preset = BellatrixPreset::from_chain_spec::<E>(spec);
    54→        let capella_preset = CapellaPreset::from_chain_spec::<E>(spec);
    55→        let deneb_preset = DenebPreset::from_chain_spec::<E>(spec);
    56→        let extra_fields = get_extra_fields(spec);
    57→
    58→        if spec.is_gloas_scheduled() {
    59→            let electra_preset = ElectraPreset::from_chain_spec::<E>(spec);
    60→            let fulu_preset = FuluPreset::from_chain_spec::<E>(spec);
    61→            let gloas_preset = GloasPreset::from_chain_spec::<E>(spec);
    62→
    63→            ConfigAndPreset::Gloas(ConfigAndPresetGloas {
    64→                config,
    65→                base_preset,
    66→                altair_preset,
    67→                bellatrix_preset,
    68→                capella_preset,
